export type RajasthanPalette = Record<keyof typeof rajasthanDefaultPalette, string>;

/* Dominant tone of the artwork, the hue/saturation reference for the `tone` remap. */
const ANCHOR = "#C35F15";

/* ---- tiny, dependency-free color helpers (hex/rgb/hsl) ---- */
function parseColor(input: string): [number, number, number] | null {
  const s = input.trim().toLowerCase();
  let m = /^#([0-9a-f]{6})$/.exec(s);
  if (m) {
    const n = parseInt(m[1], 16);
    return rgbToHsl((n >> 16) & 255, (n >> 8) & 255, n & 255);
  }
  m = /^#([0-9a-f]{3})$/.exec(s);
  if (m) {
    const h = m[1];
    return rgbToHsl(
      parseInt(h[0] + h[0], 16),
      parseInt(h[1] + h[1], 16),
      parseInt(h[2] + h[2], 16),
    );
  }
  m = /^rgba?\(\s*([\d.]+)[,\s]+([\d.]+)[,\s]+([\d.]+)/.exec(s);
  if (m) return rgbToHsl(+m[1], +m[2], +m[3]);
  m = /^hsla?\(\s*([\d.]+)[,\s]+([\d.]+)%?[,\s]+([\d.]+)%?/.exec(s);
  if (m) return [((+m[1] % 360) + 360) % 360, +m[2], +m[3]];
  return null;
}

function rgbToHsl(r: number, g: number, b: number): [number, number, number] {
  r /= 255;
  g /= 255;
  b /= 255;
  const max = Math.max(r, g, b);
  const min = Math.min(r, g, b);
  const d = max - min;
  let h = 0;
  if (d !== 0) {
    if (max === r) h = ((g - b) / d) % 6;
    else if (max === g) h = (b - r) / d + 2;
    else h = (r - g) / d + 4;
    h *= 60;
    if (h < 0) h += 360;
  }
  const l = (max + min) / 2;
  const s = d === 0 ? 0 : d / (1 - Math.abs(2 * l - 1));
  return [h, s * 100, l * 100];
}

function hslToHex(h: number, s: number, l: number): string {
  s /= 100;
  l /= 100;
  const c = (1 - Math.abs(2 * l - 1)) * s;
  const x = c * (1 - Math.abs(((h / 60) % 2) - 1));
  const m = l - c / 2;
  const [r, g, b] =
    h < 60 ? [c, x, 0] : h < 120 ? [x, c, 0] : h < 180 ? [0, c, x] : h < 240 ? [0, x, c] : h < 300 ? [x, 0, c] : [c, 0, x];
  const to = (v: number) =>
    Math.round((v + m) * 255)
      .toString(16)
      .padStart(2, "0");
  return "#" + to(r) + to(g) + to(b);
}

const clamp = (v: number, lo: number, hi: number) => Math.min(hi, Math.max(lo, v));

/** Recolor the whole ramp to `base`'s hue, preserving each shade's lightness. */
function recolor(base: string): RajasthanPalette {
  const anchor = parseColor(ANCHOR)!;
  const tone = parseColor(base);
  if (!tone) return { ...rajasthanDefaultPalette };
  const dh = tone[0] - anchor[0];
  const satScale = anchor[1] === 0 ? 1 : tone[1] / anchor[1];
  const out = {} as RajasthanPalette;
  for (const key of Object.keys(rajasthanDefaultPalette) as (keyof RajasthanPalette)[]) {
    const [h, sPct, lPct] = parseColor(rajasthanDefaultPalette[key])!;
    out[key] = hslToHex(((h + dh) % 360 + 360) % 360, clamp(sPct * satScale, 0, 100), lPct);
  }
  return out;
}

export interface RajasthanBgProps extends Omit<React.SVGProps<SVGSVGElement>, "fill"> {
  /** Recolor the whole illustration to this base color (hex / rgb() / hsl()). */
  tone?: string;
  /** Override individual shades; merged over the default (or `tone`-derived) palette. */
  palette?: Partial<RajasthanPalette>;
}

